command:
set -eu
sudo cp -a /etc/named.conf /etc/named.conf.antrieb-before
sudo sh -c 'cat > /etc/named.conf' <<'ANTRIEB_NAMED'
options {
    listen-on port 53 { 127.0.0.1; 10.100.93.10; };
    listen-on-v6 port 53 { none; };
    directory "/var/named";
    dump-file "/var/named/data/cache_dump.db";
    statistics-file "/var/named/data/named_stats.txt";
    memstatistics-file "/var/named/data/named_mem_stats.txt";
    secroots-file "/var/named/data/named.secroots";
    recursing-file "/var/named/data/named.recursing";
    allow-query { localhost; 10.100.93.0/24; };
    recursion yes;
    forwarders { 10.100.93.1; };
    forward only;
    dnssec-validation yes;
    managed-keys-directory "/var/named/dynamic";
    geoip-directory "/usr/share/GeoIP";
    pid-file "/run/named/named.pid";
    session-keyfile "/run/named/session.key";
};
logging {
    channel default_debug {
        file "data/named.run";
        severity dynamic;
    };
};
zone "." IN {
    type hint;
    file "named.ca";
};
include "/etc/named.rfc1912.zones";
include "/etc/named.root.key";
zone "internal" IN {
    type master;
    file "inventory.internal.zone";
    allow-update { none; };
};
ANTRIEB_NAMED
sudo sh -c 'cat > /var/named/inventory.internal.zone' <<'ANTRIEB_ZONE'
$TTL 300
@ IN SOA ns1.internal. hostmaster.internal. (
  2026100301 3600 900 604800 300 )
  IN NS ns1.internal.
ns1 IN A 10.100.93.10
inventory-api IN A 10.100.93.11
ANTRIEB_ZONE
sudo chown root:named /etc/named.conf
sudo chmod 640 /etc/named.conf
sudo chown root:named /var/named/inventory.internal.zone
sudo chmod 640 /var/named/inventory.internal.zone
sudo named-checkconf /etc/named.conf
sudo named-checkzone internal /var/named/inventory.internal.zone
printf '%s\n' 'configuration validation passed'

